//! 診断専用: 成功後に仕事量枠を更新しても全体期限を共有する試作。
use mip_codex::{adaptive_resource_repair::{self,Stats},solve::Result};
use std::time::{Instant,Duration};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}
 let wall=Instant::now();let m=mip_codex::mps::read(&a[1]).unwrap();let input:serde_json::Value=serde_json::from_reader(std::fs::File::open(&a[2]).unwrap()).unwrap();let mut x:Vec<_>=m.variables.iter().map(|v|input["values"][&v.name].as_f64().unwrap()).collect();let lower:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let upper:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let seconds:f64=a[3].parse().unwrap();let end=Instant::now()+Duration::from_secs_f64(seconds);let mut records=vec![];for _ in 0..16{if Instant::now()>=end{break;}let mut stats=Stats::default();let next=adaptive_resource_repair::search(&m,&x,&lower,&upper,end,512*1024*1024,&mut stats);let found=next.is_some();if let Some(v)=next{x=v;}records.push(serde_json::json!({"objective":m.objective(&x),"stats":stats}));if !found{break;}}
 assert!(m.check(&x,true,1e-7).is_ok());let r=Result{status:"feasible_adaptive_continue_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(x).map(|(v,x)|(v.name.clone(),x)).collect()),..Result::default()};serde_json::to_writer(std::fs::File::create(&a[4]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"objective":r.objective,"calls":records,"budget_seconds":seconds,"wall_seconds":wall.elapsed().as_secs_f64(),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));}
